import fs from 'node:fs';
const dir='scripts/statistics-sources/archipelago';fs.mkdirSync(dir,{recursive:true});
// Obtain the two BPS PDFs from the official publication pages in the source README.
// Download links are generated by BPS; retained, hashed snapshots reproduce the build.
const downloads={
 'exchange-rates.json':'https://api.worldbank.org/v2/country/IDN;PHL/indicator/PA.NUS.FCRF?format=json&date=2024:2025&per_page=20'
};
async function get(url){const r=await fetch(url);if(!r.ok)throw Error(url+': '+r.status);return r;}
for(const [file,url]of Object.entries(downloads)){if(fs.existsSync(dir+'/'+file))continue;try{const r=await get(url);fs.writeFileSync(dir+'/'+file,new Uint8Array(await r.arrayBuffer()));console.log(file,fs.statSync(dir+'/'+file).size);}catch(e){console.log(e.message);}}
const base='https://openstat.psa.gov.ph/PXWeb/api/v1/en/DB/2A/PPA/';
const listing=await (await get(base)).json();fs.writeFileSync(dir+'/psa-ppa-listing.json',JSON.stringify(listing,null,2));console.log('PPA tables',JSON.stringify(listing));
for(const item of listing.filter(i=>i.type==='t')){
 if(!/^(Gross Domestic Product by Province and HUC|Per Capita Gross Domestic Product by Province and HUC)$/.test(item.text))continue;
 const url=base+item.id,metadata=await(await get(url)).json();fs.writeFileSync(dir+'/'+item.id+'.metadata.json',JSON.stringify(metadata,null,2));
 const query={query:metadata.variables.map(v=>({code:v.code,selection:{filter:'item',values:v.code==='Year'?v.values.filter((code,i)=>Number(v.valueTexts[i])>=2024):v.code==='Type of Valuation'?['0']:v.values}})),response:{format:'json'}};
 fs.writeFileSync(dir+'/'+item.id+'.query.json',JSON.stringify(query,null,2));
 const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(query)});if(!response.ok)throw Error(item.id+': '+response.status);
 fs.writeFileSync(dir+'/'+item.id+'.json',JSON.stringify(await response.json(),null,2));console.log('Downloaded',item.id);
 const px=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...query,response:{format:'px'}})});if(!px.ok)throw Error(item.id+' PX: '+px.status);fs.writeFileSync(dir+'/'+item.id+'.source.px',new Uint8Array(await px.arrayBuffer()));
}
const census='https://openstat.psa.gov.ph/PXWeb/api/v1/en/DB/1A/PO_2024/';
const populationFile='0191A6DTHP8.px',population=await(await get(census+populationFile)).json();
for(const file of [populationFile,'0221A6DLPD0.px']){
 const metadata=await(await get(census+file)).json();fs.writeFileSync(dir+'/'+file+'.metadata.json',JSON.stringify(metadata,null,2));
 const query={query:metadata.variables.map(v=>({code:v.code,selection:{filter:'item',values:v.values||population.variables.find(p=>p.code===v.code).values}})),response:{format:'json'}};
 fs.writeFileSync(dir+'/'+file+'.query.json',JSON.stringify(query,null,2));
 const response=await fetch(census+file,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(query)});if(!response.ok)throw Error(file+': '+response.status+' '+await response.text());
 fs.writeFileSync(dir+'/'+file+'.json',JSON.stringify(await response.json(),null,2));console.log('Downloaded',file);
 const px=await fetch(census+file,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...query,response:{format:'px'}})});if(!px.ok)throw Error(file+' PX: '+px.status);fs.writeFileSync(dir+'/'+file+'.source.px',new Uint8Array(await px.arrayBuffer()));
}
